"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["77137"],{99573(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modalidade.cota_sem_opcao_pelas_cotas_da_lei","status":422,"titulo":"A cota da lei exige a op\xe7\xe3o pelas cotas da lei em toda cl\xe1usula"},"descricao":{"codigo":"uniplus.configuracao.modalidade.cota_sem_opcao_pelas_cotas_da_lei","requisitos":["UNI-REQ-0076","UNI-REQ-0142"],"oQueAconteceu":["A modalidade tem natureza **cota reservada** (`COTA_RESERVADA`), mas alguma cl\xe1usula de `regraDeAplicabilidade` n\xe3o exige a op\xe7\xe3o pelas cotas da lei. Toda cl\xe1usula da cota precisa conter a condi\xe7\xe3o `{\\"fato\\":\\"OPTOU_PELAS_COTAS_DA_LEI\\",\\"operador\\":\\"IGUAL\\",\\"valor\\":true}`. Uma regra sem cl\xe1usula nenhuma tamb\xe9m \xe9 recusada, pois deixaria a cota aberta a todo candidato. Nada foi gravado.","Na atualiza\xe7\xe3o, a modalidade \xe9 procurada antes desta confer\xeancia: com um identificador inexistente a resposta \xe9 [modalidade n\xe3o encontrada](/erros/uniplus.configuracao.modalidade.nao_encontrada), mesmo que o conte\xfado enviado tamb\xe9m tivesse este problema. Numa modalidade do cat\xe1logo legal fixo esta recusa n\xe3o \xe9 emitida: se o conte\xfado altera algo al\xe9m da descri\xe7\xe3o e da base legal, vale [estrutura protegida n\xe3o edit\xe1vel](/erros/uniplus.configuracao.modalidade.estrutura_protegida_nao_editavel)."],"comoResolver":["Acrescente a condi\xe7\xe3o de op\xe7\xe3o pelas cotas da lei a cada cl\xe1usula, junto das demais condi\xe7\xf5es que definem o grupo da cota (renda, origem escolar, ra\xe7a ou etnia, defici\xeancia)."],"ondeAparece":["Cria\xe7\xe3o de uma modalidade (POST /api/configuracao/admin/modalidades)","Atualiza\xe7\xe3o de uma modalidade fora do cat\xe1logo legal fixo (PUT /api/configuracao/admin/modalidades/`{id}`), depois de a modalidade ser encontrada"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modalidade"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);